CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_path text, timezone text NOT NULL DEFAULT 'UTC', content_language text NOT NULL DEFAULT 'en', appearance text NOT NULL DEFAULT 'light' CHECK (appearance IN ('light','dark')));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_own ON public.profiles FOR ALL TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_signup_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, display_name) VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'display_name', NEW.raw_user_meta_data->>'full_name', '')); RETURN NEW; END; $$;
CREATE TRIGGER create_profile_after_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_signup_profile();
INSERT INTO public.profiles(id,display_name) SELECT id, COALESCE(raw_user_meta_data->>'display_name', '') FROM auth.users ON CONFLICT DO NOTHING;
CREATE TABLE public.tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 500), next_step text NOT NULL DEFAULT '', category text NOT NULL DEFAULT 'personal' CHECK(category IN ('personal','work','school')), context_label text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','done')), due_date date, estimated_minutes integer CHECK(estimated_minutes > 0), energy_demand integer CHECK(energy_demand BETWEEN 1 AND 5), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,owner_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.tasks TO authenticated; GRANT ALL ON public.tasks TO service_role;
ALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY tasks_own ON public.tasks FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE INDEX tasks_owner ON public.tasks(owner_id,created_at);
CREATE TABLE public.daily_priorities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id) ON DELETE CASCADE, local_date date NOT NULL, task_id uuid NOT NULL, position integer NOT NULL CHECK(position BETWEEN 1 AND 3), FOREIGN KEY(task_id,owner_id) REFERENCES public.tasks(id,owner_id) ON DELETE CASCADE, UNIQUE(owner_id,local_date,position), UNIQUE(owner_id,local_date,task_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.daily_priorities TO authenticated; GRANT ALL ON public.daily_priorities TO service_role;
ALTER TABLE public.daily_priorities ENABLE ROW LEVEL SECURITY;
CREATE POLICY priorities_own ON public.daily_priorities FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE INDEX priorities_task ON public.daily_priorities(task_id,owner_id);
CREATE TABLE public.daily_checkins (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id) ON DELETE CASCADE, local_date date NOT NULL, mood integer CHECK(mood BETWEEN 1 AND 5), energy integer CHECK(energy BETWEEN 1 AND 5), UNIQUE(owner_id,local_date));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.daily_checkins TO authenticated; GRANT ALL ON public.daily_checkins TO service_role;
ALTER TABLE public.daily_checkins ENABLE ROW LEVEL SECURITY;
CREATE POLICY checkins_own ON public.daily_checkins FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE TABLE public.inbox_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN ('thought','task','link')), body text NOT NULL CHECK(length(trim(body)) BETWEEN 1 AND 10000), url text, created_at timestamptz NOT NULL DEFAULT now(), sorted_at timestamptz, task_id uuid, FOREIGN KEY(task_id,owner_id) REFERENCES public.tasks(id,owner_id) ON DELETE SET NULL (task_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.inbox_items TO authenticated; GRANT ALL ON public.inbox_items TO service_role;
ALTER TABLE public.inbox_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY inbox_own ON public.inbox_items FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE INDEX inbox_owner ON public.inbox_items(owner_id,created_at);
CREATE INDEX inbox_task ON public.inbox_items(task_id,owner_id);
CREATE FUNCTION public.convert_capture_to_task(capture_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE item public.inbox_items; new_id uuid; BEGIN SELECT * INTO item FROM public.inbox_items WHERE id=capture_id AND owner_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Capture not found'; END IF; IF item.task_id IS NOT NULL THEN RETURN item.task_id; END IF; INSERT INTO public.tasks(owner_id,title) VALUES(auth.uid(),left(item.body,500)) RETURNING id INTO new_id; UPDATE public.inbox_items SET task_id=new_id,sorted_at=now() WHERE id=capture_id; RETURN new_id; END; $$;
REVOKE ALL ON FUNCTION public.convert_capture_to_task(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.convert_capture_to_task(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.create_signup_profile() FROM PUBLIC;